async function assertCanonicalStagedBytes(db:any,group:string){
 const r=(await db.query(`WITH stage AS(SELECT coalesce(jsonb_object_agg(request_id::text,context->'detail'),'{}')details,count(*)::integer n FROM uc_group_education_requests WHERE row_kind='source_detail'AND group_id=$1 AND backend_pid=pg_backend_pid()AND full_transaction_id=pg_current_xact_id()::text)SELECT s.n,(p.context->>'live_detail_count')::integer cached_n,octet_length(s.details::text)d,(p.context->>'detail_map_serialized_bytes')::bigint cached_d,octet_length(((p.context-ARRAY['live_detail_count','detail_map_serialized_bytes'])||jsonb_build_object('details',s.details))::text)b,octet_length(((p.context-ARRAY['live_detail_count','detail_map_serialized_bytes'])||jsonb_build_object('details','{}'::jsonb))::text)-2+(p.context->>'detail_map_serialized_bytes')::bigint cached_b FROM stage s CROSS JOIN uc_group_education_requests p WHERE p.row_kind='source_pending'AND p.group_id=$1 AND p.backend_pid=pg_backend_pid()AND p.full_transaction_id=pg_current_xact_id()::text`,[group])).rows[0];
 expect(r.cached_n).toBe(r.n);expect(Number(r.cached_d)).toBe(r.d);expect(Number(r.cached_b)).toBe(r.b);return r;
}
it('extends actual115 with captured native source FKs, capacity and primary autosync without a seeded UC013 state',async()=>{
 const db=await createUcGroupEducationFixture(false);
 try{const s=await seedGroupEducationScenario(db);await db.exec('RESET ROLE');
  expect((await db.query<any>("SELECT to_regclass('public.uc_group_education_states')t")).rows[0].t).toBeNull();
  for(const key of groupEducationBaseline.fixtureSelection.primaryKeys){const row=(await db.query<any>('SELECT pg_get_constraintdef(oid,true)d FROM pg_constraint WHERE conrelid=$1::regclass AND conname=$2',['public.'+key.table,key.name])).rows[0];expect(row?.d,key.name).toBe(key.definition);}
  expect(groupEducationBaseline.fixtureSelection.indexes).toHaveLength(7);for(const index of groupEducationBaseline.fixtureSelection.indexes){const row=(await db.query<any>("SELECT tablename,indexdef FROM pg_indexes WHERE schemaname='public'AND indexname=$1",[index.name])).rows[0];expect(row).toEqual({tablename:index.table,indexdef:index.definition});}
  for(const f of groupEducationBaseline.fixtureSelection.foreignKeys){const row=(await db.query<any>('SELECT pg_get_constraintdef(oid,true)d FROM pg_constraint WHERE conrelid=$1::regclass AND conname=$2',['public.'+f.table,f.name])).rows[0];expect(row?.d,f.name).toBe(f.definition);}
  for(const t of groupEducationBaseline.fixtureSelection.triggers){const row=(await db.query<any>('SELECT pg_get_triggerdef(oid,true)d FROM pg_trigger WHERE tgrelid=$1::regclass AND tgname=$2',['public.'+t.table,t.name])).rows[0];expect(row?.d,t.name).toBe(t.definition);}
  const current=(await db.query<any>('SELECT id FROM enrollments WHERE user_id=$1 AND course_id=$2',[s.ids.student,s.ids.course])).rows;expect(current).toEqual([{id:s.ids.enrollment}]);
  const snapshots=(await db.query<any>('SELECT count(*)::integer n FROM group_program_enrollment_snapshots WHERE user_id=$1 AND group_id=$2',[s.ids.student,s.ids.group])).rows[0];expect(snapshots.n).toBe(1);
  const index=groupEducationBaseline.fixtureSelection.indexes[0];await db.exec('DROP INDEX public."'+index.name+'"');await db.exec('CREATE INDEX "'+index.name+'" ON public."'+index.table+'"(group_id)');await expect(restoreGroupEducationSourceIndexes(db)).rejects.toThrow('Actual source index mismatch: '+index.name);
 }finally{await db.close();}
},60000);
it('retains frozen group A despite a course default B and recovers an unfrozen empty group using current B only',async()=>{
 const db=await createUcGroupEducationFixture(true);try{const s=await seedGroupEducationScenario(db);const first=await s.read({kind:'state'});await s.apply(0,{action:'initialize_history',timezone:'Asia/Vladivostok',expected_program_ref:first.program_ref,reason:'Synthetic retained A'});
  const otherBefore=await s.read({kind:'state'},s.ids.otherGroup),otherInitial=await s.apply(0,{action:'initialize_history',timezone:'Asia/Vladivostok',expected_program_ref:otherBefore.program_ref,reason:'Synthetic empty A baseline'},s.request(),s.ids.otherGroup);const oldAt=otherInitial.envelope.state.coverage_known_from;
  const factsB={...s.facts,full_title:'Synthetic116 reviewed programme B'};let pv=(await db.query<any>('SELECT create_program_facts_version($1,$2,$3,NULL,$4,$5,$6,0,$7)d',[s.ids.organization,groupEducationId(5100),'Synthetic programmeB',s.file.version_id,s.ids.reviewer,JSON.stringify(factsB),s.request()])).rows[0].d;
  pv=(await db.query<any>("SELECT transition_program_facts_version($1,$2,'submit',NULL,$3)d",[pv.id,pv.revision,s.request()])).rows[0].d;await s.executeAsCaller(s.ids.reviewer);pv=(await db.query<any>("SELECT transition_program_facts_version($1,$2,'approve',NULL,$3)d",[pv.id,pv.revision,s.request()])).rows[0].d;
  await s.executeAsCaller(s.ids.owner);await db.query('SELECT bind_course_program_version($1,$2,$3,1,$4)',[s.ids.organization,s.ids.course,pv.id,s.request()]);
  const stillA=await s.read({kind:'roster',as_of:{kind:'current'},knowledge_revision:null,after_user_id:null,limit:100});expect(stillA.rows[0].association).toBe('confirmed');expect((await s.read({kind:'state'})).program_ref).toEqual(first.program_ref);
  await expect(db.query('SELECT bind_group_program_version($1,$2,$3,$4,1,$5)',[s.ids.organization,s.ids.group,s.ids.course,pv.id,s.request()])).rejects.toThrow('group_program_binding_is_frozen');
  await db.query('SELECT bind_group_program_version($1,$2,$3,$4,1,$5)',[s.ids.organization,s.ids.otherGroup,s.ids.course,pv.id,s.request()]);const gap=await s.read({kind:'state'},s.ids.otherGroup);expect(groupEducationEnvelopeSchema.parse(gap)).toEqual(gap);expect(gap.state.active_gap.reason).toBe('source_changed');expect(gap.state.program_ref.version_id).not.toBe(gap.program_ref.version_id);
  const recovered=await s.apply(gap.state.revision,{action:'recover_coverage',gap_id:gap.state.active_gap.id,expected_program_ref:gap.program_ref,reason:'Synthetic fresh B observation'},s.request(),s.ids.otherGroup);expect(groupEducationMutationSchema.parse(recovered)).toEqual(recovered);expect(recovered.envelope.state.program_ref.version_id).toBe(pv.id);
  const old=await s.read({kind:'roster',as_of:{kind:'at',at:oldAt,timezone:'Asia/Vladivostok'},knowledge_revision:1,after_user_id:null,limit:100},s.ids.otherGroup);expect(old.coverage).toBe('complete_observed');expect(old.count.exact_count).toBe(0);
  // Explicit rollback-only owner metadata fault, not a legitimate public rebind:
  // current group reference hash must match the exact immutable association.
  await db.exec('RESET ROLE');await db.exec('BEGIN');await db.query("UPDATE group_program_bindings SET snapshot_hash=repeat('a',64)WHERE group_id=$1",[s.ids.group]);const fault=(await db.query<any>('SELECT uc_group_education_scan($1,$2,clock_timestamp(),NULL,\'[]\',true)d',[s.ids.organization,s.ids.group])).rows[0].d;expect(fault.rows[0].enrollment_id).toBe(s.ids.enrollment);expect(fault.rows[0].program_enrollment_snapshot_id).toBeNull();expect(fault.rows[0].association).toBe('no_program_snapshot');await db.exec('ROLLBACK');
 }finally{await db.close();}
},60000);
it('records an IMMEDIATE multi-row statement completely and leaves a no-op insert without a ghost queue',async()=>{
 const db=await createUcGroupEducationFixture(true);try{const s=await seedGroupEducationScenario(db);await db.exec('RESET ROLE');const users=[groupEducationId(4100),groupEducationId(4101)];for(const user of users){await db.query('INSERT INTO auth.users(id)VALUES($1)',[user]);await db.query("INSERT INTO profiles(user_id,organization_id,full_name)VALUES($1,$2,'Synthetic116 new observed subject')",[user,s.ids.organization]);await db.query("INSERT INTO user_roles(user_id,role)VALUES($1,'student')",[user]);}
  await s.executeAsCaller(s.ids.owner);const first=await s.read({kind:'state'});await s.apply(0,{action:'initialize_history',timezone:'Asia/Vladivostok',expected_program_ref:first.program_ref,reason:'Synthetic multi-row boundary'});
  await db.exec('RESET ROLE');await db.exec(`CREATE TEMP TABLE uc116_budget_update_observer(old_context jsonb,new_context jsonb);CREATE FUNCTION pg_temp.uc116_observe_budget_update()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.row_kind='source_transaction_budget'THEN INSERT INTO uc116_budget_update_observer VALUES(OLD.context,NEW.context);END IF;RETURN NEW;END;$$;CREATE TRIGGER uc116_test_budget_update AFTER UPDATE ON uc_group_education_requests FOR EACH ROW EXECUTE FUNCTION pg_temp.uc116_observe_budget_update();CREATE TEMP TABLE uc116_mirror_update_observer(old_ids uuid[],new_ids uuid[]);CREATE TEMP TABLE uc116_pending_visibility(mirror_count integer,detail_present boolean,personal_count integer);CREATE FUNCTION pg_temp.uc116_observe_mirror_update()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.row_kind='source_pending'AND OLD.subject_ids IS DISTINCT FROM NEW.subject_ids THEN INSERT INTO uc116_mirror_update_observer VALUES(OLD.subject_ids,NEW.subject_ids);END IF;RETURN NEW;END;$$;CREATE TRIGGER uc116_test_mirror_update AFTER UPDATE ON uc_group_education_requests FOR EACH ROW EXECUTE FUNCTION pg_temp.uc116_observe_mirror_update();CREATE FUNCTION pg_temp.uc116_observe_pending_visibility()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE q uc_group_education_requests;n integer;BEGIN SELECT * INTO q FROM uc_group_education_requests WHERE row_kind='source_pending'AND group_id=NEW.group_id AND backend_pid=pg_backend_pid()AND full_transaction_id=pg_current_xact_id()::text;SELECT coalesce(sum((x->>'count')::integer),0)INTO n FROM jsonb_array_elements(uc_group_education_personal_counts(NEW.user_id))x;INSERT INTO uc116_pending_visibility VALUES(cardinality(q.subject_ids),EXISTS(SELECT 1 FROM uc_group_education_requests d WHERE d.row_kind='source_detail'AND d.group_id=q.group_id AND d.backend_pid=q.backend_pid AND d.full_transaction_id=q.full_transaction_id AND d.request_id=NEW.user_id),n);RETURN NEW;END;$$;CREATE TRIGGER bbb_uc116_test_pending_visibility AFTER INSERT ON student_group_memberships FOR EACH ROW EXECUTE FUNCTION pg_temp.uc116_observe_pending_visibility()`);await db.exec('BEGIN');await db.exec('SET CONSTRAINTS ALL IMMEDIATE');await db.query('INSERT INTO student_group_memberships(organization_id,group_id,user_id)SELECT $1,$2,unnest($3::uuid[])',[s.ids.organization,s.ids.group,users]);await db.exec('COMMIT');await s.executeAsCaller(s.ids.owner);
  const current=await s.read({kind:'state'});expect(groupEducationEnvelopeSchema.parse(current)).toEqual(current);expect(current.state.active_gap).toBeNull();expect((await s.read({kind:'roster',as_of:{kind:'current'},knowledge_revision:null,after_user_id:null,limit:100})).rows).toHaveLength(3);
  await db.exec('RESET ROLE');const writes=(await db.query<any>(`SELECT count(*)FILTER(WHERE old_context=new_context)::integer identical,count(*)FILTER(WHERE old_context->>'statement_depth'IS NULL AND new_context->>'statement_depth'IS NOT NULL)::integer opened,count(*)FILTER(WHERE coalesce((old_context->>'statement_constraint_seen')::boolean,false)=false AND(new_context->>'statement_constraint_seen')::boolean=true)::integer seen,count(*)FILTER(WHERE(old_context->>'admitted_detail_count')::integer IS DISTINCT FROM(new_context->>'admitted_detail_count')::integer)::integer admitted FROM uc116_budget_update_observer`)).rows[0];expect(writes).toEqual({identical:0,opened:1,seen:1,admitted:2});const mirrors=(await db.query<any>('SELECT old_ids,new_ids FROM uc116_mirror_update_observer')).rows;expect(mirrors).toEqual([{old_ids:[],new_ids:users}]);const visibility=(await db.query<any>('SELECT * FROM uc116_pending_visibility')).rows;expect(visibility).toHaveLength(2);for(const row of visibility){expect(row.mirror_count).toBe(0);expect(row.detail_present).toBe(true);expect(row.personal_count).toBeGreaterThan(0);}

 }finally{await db.close();}
},60000);
